<?php
require __DIR__.'/../../../config/database.php';
$rows=$conn->query("SELECT 'visitantes' entidade,id,morador_nome,bloco,apartamento FROM visitantes WHERE morador_id IS NULL UNION ALL SELECT 'encomendas',id,morador_nome,bloco,apartamento FROM encomendas WHERE morador_id IS NULL UNION ALL SELECT 'veiculos',id,morador_nome,bloco,apartamento FROM veiculos WHERE morador_id IS NULL ORDER BY entidade,id".pagination_sql())->fetch_all(MYSQLI_ASSOC);pagination($rows);
$duplicates=$conn->query("SELECT bloco,apartamento,COUNT(*) total FROM moradores WHERE tipo_morador='Proprietário' GROUP BY bloco,apartamento HAVING COUNT(*)>1")->fetch_all(MYSQLI_ASSOC);
$names=['visitantes'=>'visitante','encomendas'=>'encomenda','veiculos'=>'veiculo'];
?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pendências de dados</title><link rel="stylesheet" href="<?= esc(base_url('assets/css/app.css')) ?>"></head><body><main class="admin-main"><a href="<?= esc(base_url()) ?>">Voltar ao painel</a><h1>Pendências de dados</h1><h2>Registros sem morador confirmado</h2><p>Edite cada registro e selecione o responsável correto. Nenhum vínculo ambíguo foi atribuído automaticamente.</p><table><thead><tr><th>Registro</th><th>Nome antigo</th><th>Unidade</th><th>Ação</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?= esc($row['entidade'].' #'.$row['id']) ?></td><td><?= esc($row['morador_nome']) ?></td><td><?= esc($row['bloco'].' / '.$row['apartamento']) ?></td><td><a href="<?= esc(base_url('telas/telasCadastro/cadastro_'.$names[$row['entidade']].'.php?id='.$row['id'])) ?>">Corrigir vínculo</a></td></tr><?php endforeach ?></tbody></table><?php pagination_links() ?><h2>Unidades com proprietários duplicados</h2><?php if(!$duplicates):?><p>Nenhuma duplicidade.</p><?php endif ?><?php foreach($duplicates as $row):?><p>Bloco <?= esc($row['bloco']) ?> · Apto <?= esc($row['apartamento']) ?>: <?= (int)$row['total'] ?> proprietários. <a href="<?= esc(base_url('telas/telasPrincipais/moradores.php')) ?>">Revisar moradores</a></p><?php endforeach ?></main></body></html>
